#!/usr/bin/env python3
import re
p="index.html"
html=open(p,encoding="utf-8").read()
def block_span(html,id_attr,tag="div"):
    m=re.search(r'(<%s[^>]*id="%s"[^>]*>)'%(tag,re.escape(id_attr)),html)
    if not m: raise SystemExit(f"not found {id_attr}")
    start=m.end(); depth=1; pat=re.compile(r'</?%s\b[^>]*>'%tag)
    for mm in pat.finditer(html,start):
        if mm.group(0).startswith('</'):
            depth-=1
            if depth==0: return start,mm.start()
        elif not mm.group(0).endswith('/>'): depth+=1
    raise SystemExit("unbalanced")
def replace_block(html,id_attr,new_inner,tag="div"):
    s,e=block_span(html,id_attr,tag); return html[:s]+new_inner+html[e:]
def sub(pattern,repl,html,flags=0,label=""):
    new,n=re.subn(pattern,repl,html,count=1,flags=flags)
    if n==0: raise SystemExit(f"pattern not found: {label or pattern[:90]}")
    return new

html=sub(r'<meta name="fg-edition" content="[^"]*">','<meta name="fg-edition" content="2026-11-24-evening">',html,label="fg-edition")
html=sub(r'<!-- EDITION:NAME -->.*?<!-- /EDITION:NAME -->','<!-- EDITION:NAME --> Evening Edition — published 5:30 PM PT <!-- /EDITION:NAME -->',html,flags=re.S,label="edition")
html=sub(r'<!-- WEATHER:BUG -->.*?<!-- /WEATHER:BUG -->','<!-- WEATHER:BUG --> 🐕 Two dogs in the roadway on Shenandoah Rd at Bell Rd (CHP, 5:09 PM); SR-88 tree work done for the day; mostly cloudy tonight, low 48°; no NWS alert (CHP / Caltrans / NWS) <!-- /WEATHER:BUG -->',html,flags=re.S,label="bug")
html=sub(r'<!-- LEAD:HEADLINE -->.*?<!-- /LEAD:HEADLINE -->','<!-- LEAD:HEADLINE --> Evening in the foothills — two dogs are in the roadway on Shenandoah Rd at Bell Rd, SR-88&#8217;s tree work has wrapped for the day, and Tapas Tuesday pours at Krissie Vineyards until 7 PM <!-- /LEAD:HEADLINE -->',html,flags=re.S,label="headline")
html=sub(r'<p><!-- LEAD:BODY -->.*?</p>','<p><!-- LEAD:BODY --> Evening settles over a mostly cloudy Tuesday that topped out near 59. The day&#8217;s one live caution is fresh: <b>CHP logged two large dogs in the roadway on Shenandoah Rd at Bell Rd at 5:09 PM</b>, with a unit en route — slow down on the Shenandoah Rd run tonight (see the Safety Wire). Caltrans&#8217; <b>tree work on SR-88 near the SR-124 junction and at McFadden Street in Pine Grove wrapped at 5:00 PM</b>, and <b>no chain control stands on SR-88</b>; SR-49, SR-124, and SR-104 all report no restrictions. <b>No National Weather Service alert is in effect</b> for the Fiddletown point. Of today&#8217;s four database listings, the <b>Sierra Oak Farms veggie stand</b> sold its <b>last day</b> at Fiddletown Rd and Mt. Whitney, the <b>Rotary Club packed Thanksgiving boxes</b> in Plymouth this morning, and <b>Baked in Amador&#8217;s preorder pickup</b> ran in Volcano until 3:00 PM — it returns Wednesday, 11:00 AM–3:00 PM. The evening&#8217;s remaining event is <b>Tapas Tuesday at Krissie Vineyards</b> on Shenandoah Rd in Plymouth, pouring until 7:00 PM. Tonight stays mostly cloudy, low near 48 and rising to about 50 overnight — Wednesday reads sunny, high near 63, and Thanksgiving Day mostly sunny, high near 62. <!-- /LEAD:BODY --></p>',html,flags=re.S,label="lead body")

